//! 🎟️ Actual painted-scene storage is denied before effects and closes under the same finite original.
use {semio_s_artifact_draw_drawing_scene::preparation::{DocumentScenePlan,DocumentSceneNode,DocumentSceneContent},semio_s_artifact_draw_drawing_scene_paint::scene::*};
use semio_framework_value_persistent::work::RetainedWorkLedger;
use semio_framework_value::{RetainedCloneGrant,RetirementDemand};
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,OriginalTurnFailure,OperationId,Generation,close_original_retained_step};
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
use serde_json::Value;
fn rows()->Value{serde_json::from_str(include_str!("../../🎟️work/🧫️fixtures/🔣️.json")).unwrap()}
fn grant(v:&Value)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:v["items"].as_u64().unwrap()as usize,maximum_copy_bytes:v["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:v["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:v["release"].as_u64().unwrap()as usize,maximum_depth:v["depth"].as_u64().unwrap()as usize}}
fn now()->Option<u64>{Some(0)}
fn limits()->PaintedSceneLimits{PaintedSceneLimits{max_nodes:4,max_segments:64,max_points:128,max_contours:8,max_work:10000}}
fn image(v:&Value)->DocumentScenePlan{let mut transform=[0.;6];for(i,n)in v["transform"].as_array().unwrap().iter().enumerate(){transform[i]=n.as_f64().unwrap();}DocumentScenePlan{assets:Vec::new(),nodes:vec![DocumentSceneNode{source_path:vec![0],locked_ancestors:0,id:"image".into(),groups:Vec::new(),transform,opacity:1.,blend_mode:"normal".into(),visible:true,content:DocumentSceneContent::Image{asset:"image-source".into(),width:v["width"].as_f64().unwrap(),height:v["height"].as_f64().unwrap()}}]}}
fn demand<T>(owner:&T)->RetirementDemand where T:CloseOwner{RetirementDemand{copy_bytes:owner.copy(),capacity_bytes:owner.capacity(),release_bytes:owner.release(),depth:owner.depth()}}
trait CloseOwner{fn empty(&self)->bool;fn copy(&self)->usize;fn capacity(&self)->usize;fn release(&self)->usize;fn depth(&self)->usize;fn close(&mut self,g:RetainedCloneGrant)->semio_framework_value::RetainedCloneStep;}
macro_rules! owner{($t:ty)=>{impl CloseOwner for $t{fn empty(&self)->bool{self.terminal_is_empty()}fn copy(&self)->usize{self.next_copy_byte_demand().unwrap()}fn capacity(&self)->usize{let c=self.copy();self.next_capacity_byte_demand(if c>0{c}else{self.release()}).unwrap()}fn release(&self)->usize{self.next_release_byte_demand().unwrap()}fn depth(&self)->usize{self.next_depth_demand().unwrap()}fn close(&mut self,g:RetainedCloneGrant)->semio_framework_value::RetainedCloneStep{self.close_step(g).unwrap()}}};}
owner!(ScenePaintRetirement);owner!(PreparedSceneCloseJob);
fn close<T:CloseOwner>(mut owner:T,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,turn:RetainedCloneGrant,max:usize){for _ in 0..max{if owner.empty(){break}let d=demand(&owner);let(result,heap)=observe(||caller.turn_with_decoder(turn,decoder,|cx|cx.with_original_retirement(|cx|close_original_retained_step(cx,d,|g|Ok(owner.close(g))))));result.unwrap();let p=caller.receipt();assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));}assert!(owner.empty());let((),h)=observe(||drop(owner));assert!(!h.overflowed);assert_eq!((h.requested_bytes,h.released_bytes),(0,0));}
#[test]
fn painted_scene_original_funds_actual_geometry_and_preserves_image_bounds(){
 let v=rows();let stock=grant(&v["stock"]);let turn=grant(&v["turn"]);let max=v["maximumTurns"].as_u64().unwrap()as usize;let plan=image(&v["image"]);let ptr=plan.nodes.as_ptr();let(mut job,h)=observe(||ScenePaintJob::new(plan,0.001,limits()));assert!(!h.overflowed);assert_eq!((h.requested_bytes,h.released_bytes),(0,0));let mut caller=OriginalJobFixtureCaller::admit(OperationId(9317),Generation(1),stock,now,1000000,100000);let mut decoder=OriginalJobDecodeOwner::empty();let mut done=false;let mut work=0;let mut saw_capacity=false;let mut saw_copy=false;
 for _ in 0..max{
  let d=job.next_work_demand();for axis in v["axes"].as_array().unwrap(){let axis=axis.as_str().unwrap();if match axis{"items"=>false,"copy"=>d.copy_bytes==0,"capacity"=>d.capacity_bytes==0,"release"=>d.release_bytes==0,"depth"=>d.depth==0,_=>unreachable!()}{continue}let mut g=turn;match axis{"items"=>g.maximum_items=0,"copy"=>g.maximum_copy_bytes=d.copy_bytes-1,"capacity"=>g.maximum_capacity_bytes=d.capacity_bytes-1,"release"=>g.maximum_release_bytes=d.release_bytes-1,"depth"=>g.maximum_depth=d.depth-1,_=>unreachable!()}let mut ledger=RetainedWorkLedger::new(g);let(result,h)=observe(||job.advance(1,&mut ledger));let p=result.unwrap();assert_eq!(p.work,work);assert_eq!(job.last_turn_work(),0);assert_eq!(ledger.receipt(),Default::default());assert!(!h.overflowed);assert_eq!((h.requested_bytes,h.released_bytes),(0,0));assert_eq!(job.plan.as_ref().unwrap().nodes.as_ptr(),ptr);}
  let fuel=caller.fuel_remaining();let(result,h)=observe(||caller.turn_with_decoder(turn,&mut decoder,|cx|Ok::<_,OriginalTurnFailure>(job.advance_original(cx))));let p=caller.receipt();assert!(!h.overflowed);assert!(p.fits(turn));assert_eq!((h.requested_bytes,h.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert_eq!(fuel-caller.fuel_remaining(),job.last_turn_work());saw_capacity|=p.retained_capacity_bytes>0;saw_copy|=p.copied_bytes>0;let progress=result.unwrap().unwrap();assert!(progress.work>=work);work=progress.work;if progress.done{done=true;break}
 }assert!(done&&saw_capacity&&saw_copy);let(close_job,scene)=job.into_retirement();let scene=scene.unwrap();assert_eq!(scene.plan.nodes.as_ptr(),ptr);let b=scene.geometry[0].bounds.unwrap();for(i,n)in v["image"]["bounds"].as_array().unwrap().iter().enumerate(){assert_eq!(b[i],n.as_f64().unwrap());}let mut points=[tiny_skia::Point::from_xy(0.,0.),tiny_skia::Point::from_xy(3.,2.)];tiny_skia::Transform::from_row(2.,0.,0.,3.,7.,11.).map_points(&mut points);assert_eq!(b,[points[0].x as f64,points[0].y as f64,points[1].x as f64,points[1].y as f64]);close(close_job,&mut caller,&mut decoder,turn,max);close(PreparedSceneCloseJob::new(scene),&mut caller,&mut decoder,turn,max);
 for _ in 0..max{if decoder.terminal_is_empty(){break}caller.turn(turn,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(32768)?;decoder.close_on_source(cx)?;Ok(())})).unwrap();}assert!(decoder.terminal_is_empty());caller.retire(turn);
}
#[test]
fn painted_scene_cached_literal_error_and_cancel_transfer_are_heap_free(){
 let v=rows();let mut plan=image(&v["image"]);plan.nodes[0].transform[0]=f64::NAN;let mut job=ScenePaintJob::new(plan,0.001,limits());let mut wallet=super::scene_funding::Wallet::from_grant(grant(&v["stock"]),v["maximumTurns"].as_u64().unwrap()as usize);let mut failed=false;for _ in 0..16{let result=wallet.turn(1,|ledger|job.advance(1,ledger));if result.is_err(){assert_eq!(job.last_turn_work(),1);failed=true;break}}assert!(failed);let mut zero=RetainedWorkLedger::new(Default::default());let(e,h)=observe(||job.advance(1,&mut zero));assert!(e.is_err());assert_eq!(job.last_turn_work(),0);assert_eq!(zero.receipt(),Default::default());assert!(!h.overflowed);assert_eq!((h.requested_bytes,h.released_bytes),(0,0));job.cancel();let((close_job,output),h)=observe(||job.into_retirement());assert!(output.is_none());assert!(!h.overflowed);assert_eq!((h.requested_bytes,h.released_bytes),(0,0));wallet.close_owned(close_job);
}
